<div class="page-heading"><div><a href="<?= e(url('/sanitario')) ?>" class="text-link mb-3"><?= icon('arrow-left', 'h-3.5 w-3.5') ?> Módulos sanitarios</a><span class="eyebrow block">Consulta operativa</span><h1><?= e($definition['label'] ?? 'Todos los registros sanitarios') ?></h1><p><?= e($definition['description'] ?? 'Consulta y filtra todos los registros sin recortar el historial.') ?></p></div><?php if ($type !== ''): ?><a href="<?= e(url('/sanitario/registros/nuevo?tipo=' . rawurlencode($type))) ?>" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Nuevo registro</a><?php endif; ?></div>
<section class="ios-card mt-6 p-4 sm:p-5"><form method="get" action="<?= e(url('/sanitario/registros')) ?>" class="grid gap-3 md:grid-cols-[minmax(180px,1fr)_minmax(220px,1fr)_auto] md:items-end"><div><label class="label" for="sanitary-type">Módulo</label><select id="sanitary-type" name="tipo" class="input"><option value="">Todos los módulos</option><?php foreach ($types as $key => $item): ?><option value="<?= e($key) ?>"<?= selected($type, $key) ?>><?= e($item['label']) ?></option><?php endforeach; ?></select></div><div><label class="label" for="sanitary-search">Buscar en todos los campos</label><input id="sanitary-search" name="q" type="search" class="input" value="<?= e($search) ?>" placeholder="Título, responsable, observaciones o contenido"></div><div class="flex gap-2"><button class="btn-primary" type="submit"><?= icon('filter', 'h-4 w-4') ?> Filtrar</button><a href="<?= e(url('/sanitario/registros')) ?>" class="btn-ghost">Limpiar</a></div></form></section>
<section class="ios-card mt-6 overflow-hidden"><div class="card-heading"><div><h2>Historial completo</h2><p><?= count($records) ?> registros en esta vista.</p></div></div><?php if ($records === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('documents', 'h-7 w-7') ?></span><h3>No hay registros en esta vista</h3><p>Crea un registro desde el módulo correspondiente o cambia los filtros.</p><?php if ($type !== ''): ?><a href="<?= e(url('/sanitario/registros/nuevo?tipo=' . rawurlencode($type))) ?>" class="btn-primary mt-5">Crear registro</a><?php endif; ?></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Registro</th><th>Módulo</th><th>Fecha</th><th>Responsable</th><th>Requerimiento</th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><a href="<?= e(url('/sanitario/registros/' . $record['id'])) ?>" class="block max-w-[300px] text-xs font-semibold leading-5 text-slate-700 hover:text-blue-600"><?= e($record['titulo']) ?></a></td><td class="text-xs text-slate-500"><?= e($types[$record['tipo']]['label'] ?? $record['tipo']) ?></td><td class="whitespace-nowrap text-xs text-slate-500"><?= e(format_date($record['fecha_registro'])) ?></td><td class="max-w-[180px] text-xs leading-5 text-slate-500"><?= e($record['responsable']) ?></td><td><?php if ($record['requerimiento_codigo']): ?><span class="badge badge-gray"><?= e($record['requerimiento_codigo']) ?> · <?= e($record['numero_acta']) ?></span><?php else: ?><span class="text-xs text-slate-400">Sin vínculo</span><?php endif; ?></td><td><span class="badge <?= status_class($record['estado']) ?>"><?= e($record['estado']) ?></span></td><td><div class="flex gap-1"><a href="<?= e(url('/sanitario/registros/' . $record['id'])) ?>" class="btn-ghost h-8 px-2" aria-label="Consultar"><?= icon('eye', 'h-4 w-4') ?></a><a href="<?= e(url('/sanitario/registros/' . $record['id'] . '/editar')) ?>" class="btn-ghost h-8 px-2" aria-label="Editar"><?= icon('edit', 'h-4 w-4') ?></a></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
